<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">Success!</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ShipC</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> added</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> at</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> (0, </span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">0</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
